-- Synthetic local-only policy/upload lifecycle, all rows rolled back.
begin;
do $$declare org uuid=gen_random_uuid();other uuid=gen_random_uuid();actor uuid;r uuid;a uuid;fa uuid;e uuid;rev uuid;j jsonb;rec uuid;c uuid;platform uuid=gen_random_uuid();pa uuid;begin
select id into strict actor from public.profiles limit 1;
insert into public.organizations(id,name,slug) values(org,'Recording test','rec-'||org::text),(other,'Foreign test','rec-'||other::text);
insert into public.organization_modules(organization_id,module_key,is_enabled) values(org,'pbx',true),(other,'pbx',true);
insert into public.roles(organization_id,name) values(org,'Fixture') returning id into r;
insert into public.organization_members(organization_id,user_id,role_id,is_owner) values(org,actor,r,true);
-- New owner independent permissions, explicit overrides remain authoritative.
insert into public.user_permission_overrides(organization_id,user_id,permission_id,is_allowed) select org,actor,id,true from public.permissions where key in ('pbx.recordings.manage','pbx.recordings.view') on conflict do nothing;
insert into public.pbx_agents(organization_id,label,public_key) values(org,'Recording agent',encode(uuid_send(gen_random_uuid())||uuid_send(gen_random_uuid()),'base64')) returning id into a;
insert into public.pbx_agents(organization_id,label,public_key) values(other,'Foreign agent',encode(uuid_send(gen_random_uuid())||uuid_send(gen_random_uuid()),'base64')) returning id into fa;
insert into public.pbx_extensions(organization_id,number,display_name,provisioning_status) values(org,501,'Recording test','applied') returning id into e;
perform set_config('request.jwt.claim.sub',actor::text,true);
if (public.pbx_get_recording_policy(org)->>'enabled')::boolean then raise exception 'Default policy enabled';end if;
j=public.pbx_save_recording_policy(org,'{}',false);if (j->>'enabled')::boolean then raise exception 'Draft enabled';end if;
begin perform public.pbx_save_recording_policy(org,'{"enabled":true,"purpose":"Quality","legal_basis":"consent","information_reference":"Privacy"}',true);raise exception 'Offline enabled';exception when raise_exception then if sqlerrm='Offline enabled' then raise;end if;end;
update public.pbx_agents set protocol_version=3,profile_id=organization_id,profile_context='uwi-'||replace(organization_id::text,'-',''),last_sequence=10,capability_seen_at=now() where id=a;
if public.pbx_admit_recording_poll(a,9,'["recordings_v1"]') then raise exception 'Wrong sequence accepted';end if;
if not public.pbx_admit_recording_poll(a,10,'["recordings_v1"]') or public.pbx_admit_recording_poll(a,10,'["recordings_v1"]') then raise exception 'Capability replay';end if;
j=public.pbx_save_recording_policy(org,'{"enabled":true,"notice_enabled":false,"purpose":"Quality","legal_basis":"consent","information_reference":"Privacy"}',true);rev=(j->>'revision')::uuid;
if public.pbx_report_recording_policy(a,gen_random_uuid(),'applied',null) or not public.pbx_report_recording_policy(a,rev,'applied',null) or public.pbx_report_recording_policy(a,rev,'failed','secret') then raise exception 'ACK revision/status guard';end if;
insert into public.pbx_call_logs(organization_id,agent_id,event_id,linked_id,started_at,answered_at,ended_at,source,destination,source_extension_id,direction,disposition,duration_seconds,billable_seconds) values(org,a,'recording:1','recording',clock_timestamp(),clock_timestamp(),clock_timestamp()+interval '1 second','501','502',e,'internal','ANSWERED',1,1) returning id into c;
j=jsonb_build_object('call_log_id',c,'event_id','recording:1','policy_revision',rev,'scope','internal','size_bytes',64,'sha256',repeat('a',64),'duration_seconds',1);
rec=(public.pbx_prepare_recording_upload(a,j)->>'id')::uuid;
if (public.pbx_prepare_recording_upload(a,j)->>'id')::uuid<>rec then raise exception 'Idempotency';end if;
begin perform public.pbx_prepare_recording_upload(fa,j);raise exception 'Foreign agent accepted';exception when raise_exception then if sqlerrm='Foreign agent accepted' then raise;end if;end;
if public.pbx_finish_recording_upload(a,rec) then raise exception 'Missing object accepted';end if;
insert into storage.objects(bucket_id,name,metadata) select 'pbx-call-recordings',storage_path,'{"size":63}' from public.pbx_call_recordings where id=rec;
if public.pbx_finish_recording_upload(a,rec) then raise exception 'Wrong size accepted';end if;
update storage.objects set metadata='{"size":64}' where bucket_id='pbx-call-recordings';
if not public.pbx_finish_recording_upload(a,rec) then raise exception 'Valid object rejected';end if;
perform public.pbx_save_recording_policy(org,'{"enabled":false,"scopes":[]}',false);
if (public.pbx_prepare_recording_upload(a,j)->>'id')::uuid<>rec then raise exception 'Completed previous revision lost after edit';end if;
if public.pbx_authorize_recording_playback(rec) is null then raise exception 'Playback denied';end if;
j=public.pbx_list_recordings(org);if jsonb_array_length(j)<>1 or j::text like '%storage_path%' or j::text like '%sha256%' then raise exception 'List disclosure';end if;
update public.user_permission_overrides set is_allowed=false where organization_id=org and user_id=actor and permission_id=(select id from public.permissions where key='pbx.recordings.view');
if public.pbx_authorize_recording_playback(rec) is not null then raise exception 'Explicit deny ignored';end if;
update public.pbx_call_recordings set expires_at=now()-interval '1 second' where id=rec;
if public.pbx_authorize_recording_playback(rec) is not null then raise exception 'Expired playback';end if;
if jsonb_array_length(public.pbx_claim_recording_purge(a))<>1 or public.pbx_finish_recording_purge(a,rec) then raise exception 'Purge before blob removed';end if;
insert into public.organizations(id,name,slug,settings) values(platform,'Retention platform fixture','retention-platform-'||platform::text,'{"is_platform_operator":true}');
insert into public.pbx_agents(organization_id,label,public_key,protocol_version,last_sequence,capability_seen_at) values(platform,'Retention worker',encode(uuid_send(gen_random_uuid())||uuid_send(gen_random_uuid()),'base64'),2,1,now()) returning id into pa;
if not public.pbx_admit_recording_poll(pa,1,'["recordings_v1"]') then raise exception 'Platform housekeeping admission';end if;
update private.pbx_recording_capabilities set seen_at=now()-interval '96 seconds' where agent_id=pa;
update public.organization_modules set is_enabled=false where organization_id=org and module_key='pbx';
update public.pbx_agents set enabled=false where id=a;
if public.pbx_claim_recording_purge(a)<>'[]'::jsonb then raise exception 'Disabled tenant purge bypass';end if;
if jsonb_array_length(public.pbx_claim_recording_purge(pa))<>1 or public.pbx_finish_recording_purge(pa,rec) then raise exception 'Platform purge scope/object guard';end if;
delete from storage.objects where bucket_id='pbx-call-recordings';
if jsonb_array_length(public.pbx_claim_recording_purge(pa))<>1 or not public.pbx_finish_recording_purge(pa,rec) then raise exception 'Offline company retention failed';end if;
update public.organization_modules set is_enabled=true where organization_id=org and module_key='pbx';
update public.pbx_agents set enabled=true where id=a;
update private.pbx_recording_capabilities set seen_at=now()-interval '96 seconds' where agent_id=a;
if public.pbx_poll_recording_policy(a) is not null or public.pbx_report_recording_policy(a,rev,'applied',null) then raise exception 'Stale capability';end if;
if has_function_privilege('anon','public.pbx_list_recordings(uuid,integer)','execute') or has_function_privilege('authenticated','public.pbx_prepare_recording_upload(uuid,jsonb)','execute') or has_table_privilege('authenticated','public.pbx_call_recordings','select') or exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pbx_%recording%' and p.prosecdef) then raise exception 'Unsafe ACL/wrapper';end if;
end;$$;
rollback;
